const body = $json.body || $json;
const rawData = JSON.stringify(body).substring(0, 2000);

// Helper: search answers array or flat body for a field by keyword
function findAnswer(answers, body, keywords) {
  if (answers && Array.isArray(answers)) {
    for (const a of answers) {
      const q = (a.question || a.label || a.key || '').toLowerCase();
      for (const kw of keywords) {
        if (q.includes(kw)) return a.answer || a.value || a.response || '';
      }
    }
  }
  // Also check flat body keys
  for (const kw of keywords) {
    for (const [k, v] of Object.entries(body)) {
      if (k.toLowerCase().includes(kw) && typeof v === 'string') return v;
    }
  }
  return '';
}

let name = body.name || body.contact_name || body.full_name || '';
let email = body.email || body.contact_email || '';
let phone = body.phone || body.mobile || body.contact_phone || '';
let bookingDate = body.booking_date || body.start_time || body.date || body.scheduled_at || '';

// DaySchedule sends answers array with form responses
const answers = body.answers || body.questions || body.responses || body.form_data || [];

// Extract rich form data from DaySchedule booking questions
const website = findAnswer(answers, body, ['website', 'brand\'s website', 'url', 'site']);
const leadSource = findAnswer(answers, body, ['find us', 'found us', 'hear about', 'source', 'how did you']);
const revenue = findAnswer(answers, body, ['revenue', 'monthly revenue', 'current revenue']);
const services = findAnswer(answers, body, ['looking for', 'services', 'what are you looking']);
const challenges = findAnswer(answers, body, ['challenge', 'biggest content', 'pain point', 'problem']);
const urgency = findAnswer(answers, body, ['urgent', 'urgently', 'timeline', 'when', 'get started']);
const budget = findAnswer(answers, body, ['budget', 'content budget', 'monthly budget']);
const perfMarketing = findAnswer(answers, body, ['performance marketing', 'meta and google', 'manage my']);
const idealOutcome = findAnswer(answers, body, ['ideal outcome', 'outcome for you', 'expect from']);

// Derive company from website if not directly provided
let company = body.company || body.company_name || '';
if (!company && website) {
  company = website.replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].split('.')[0];
  company = company.charAt(0).toUpperCase() + company.slice(1);
}

// Map lead source to channel
let channel = 'calendar';
if (leadSource.toLowerCase().includes('instagram') || leadSource.toLowerCase().includes('meta') || leadSource.toLowerCase().includes('fb')) channel = 'paid_social';
else if (leadSource.toLowerCase().includes('google')) channel = 'paid_search';
else if (leadSource.toLowerCase().includes('referral') || leadSource.toLowerCase().includes('friend')) channel = 'referral';
else if (leadSource.toLowerCase().includes('linkedin')) channel = 'linkedin';

// Build rich notes
const noteLines = ['=== BOOKING FORM DATA ==='];
if (bookingDate) noteLines.push('Call booked for: ' + bookingDate);
if (website) noteLines.push('Website: ' + website);
if (leadSource) noteLines.push('Source: ' + leadSource);
if (revenue) noteLines.push('Monthly Revenue: ' + revenue);
if (services) noteLines.push('Services Interested: ' + services);
if (challenges) noteLines.push('Content Challenges: ' + challenges);
if (urgency) noteLines.push('Urgency: ' + urgency);
if (budget) noteLines.push('Budget: ' + budget);
if (perfMarketing) noteLines.push('Performance Marketing: ' + perfMarketing);
if (idealOutcome) noteLines.push('Ideal Outcome: ' + idealOutcome);

// Build lead fields for Airtable (field names match Leads table schema)
// Note: source is a select field — only use predefined values
const leadFields = {
  contact_name: name,
  email: email,
  stage: 'New'
};
if (phone) leadFields.phone = phone;
if (company) leadFields.company_name = company;
if (website) leadFields.website = website;
// Set next_follow_up to booking date or 2 days from now
if (bookingDate) {
  try { leadFields.next_follow_up = new Date(bookingDate).toISOString().split('T')[0]; } catch(e) {}
}
if (!leadFields.next_follow_up) {
  const d = new Date(); d.setDate(d.getDate() + 2);
  leadFields.next_follow_up = d.toISOString().split('T')[0];
}
leadFields.notes = noteLines.join('\n');

return [{
  json: {
    leadFields,
    leadName: name,
    company: company || '(not provided)',
    email,
    phone,
    bookingDate,
    website,
    leadSource,
    revenue,
    services,
    challenges,
    urgency,
    budget,
    perfMarketing,
    idealOutcome,
    rawData
  }
}];

const lead = $('cal-parse-booking').first().json;
const airtableResult = $json;
const recordId = airtableResult?.id || 'unknown';
const error = airtableResult?.error || airtableResult?.statusCode >= 400;

let message = '';
if (error) {
  message = `:warning: *Calendar Booking — Lead Creation Failed*\n\n` +
    `*Name:* ${lead.leadName}\n` +
    `*Email:* ${lead.email}\n` +
    `*Company:* ${lead.company}\n` +
    `*Booking:* ${lead.bookingDate || 'N/A'}\n\n` +
    `_Error: Failed to create lead in Airtable. Please add manually._`;
} else {
  message = `:calendar: *New Call Booking Received*\n\n` +
    `*Name:* ${lead.leadName}\n` +
    `*Email:* ${lead.email}\n` +
    `*Phone:* ${lead.phone || 'N/A'}\n` +
    `*Company:* ${lead.company}\n`;
  if (lead.website) message += `*Website:* ${lead.website}\n`;
  message += `*Booking:* ${lead.bookingDate || 'N/A'}\n\n`;
  if (lead.leadSource) message += `:mag: *Source:* ${lead.leadSource}\n`;
  if (lead.revenue) message += `:chart_with_upwards_trend: *Revenue:* ${lead.revenue}\n`;
  if (lead.budget) message += `:moneybag: *Budget:* ${lead.budget}\n`;
  if (lead.urgency) message += `:zap: *Urgency:* ${lead.urgency}\n`;
  if (lead.services) message += `\n:dart: *Services Interested:*\n${lead.services}\n`;
  if (lead.challenges) message += `\n:warning: *Content Challenges:*\n${lead.challenges}\n`;
  if (lead.perfMarketing) message += `\n:bar_chart: *Perf Marketing:* ${lead.perfMarketing}\n`;
  if (lead.idealOutcome) message += `\n:star: *Ideal Outcome:* ${lead.idealOutcome}\n`;
  message += `\n_Lead added to pipeline (ID: ${recordId})_`;
}

return [{ json: { message, leadName: lead.leadName, company: lead.company, _error: !!error } }];
